package kr.pdfmemorynotes;

import android.app.*;
import android.content.*;
import android.content.ClipboardManager;
import android.graphics.*;
import android.net.Uri;
import android.text.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.util.*;

/** A per-document durable clipboard draft. Nothing is inferred from the PDF. */
final class ManualCards {
 final MainActivity a;
 final long doc;
 final SharedPreferences prefs;
 String question="",answer="";
 JSONArray qi=new JSONArray(),ai=new JSONArray();
 boolean pickerAnswer,busy;AlertDialog editor;
 TextView summary;
 ManualCards(MainActivity a,long doc){this.a=a;this.doc=doc;prefs=a.getSharedPreferences("manual",0);try{JSONObject d=new JSONObject(prefs.getString("draft:"+doc,"{}"));question=d.optString("q");answer=d.optString("a");qi=d.optJSONArray("qi");ai=d.optJSONArray("ai");if(qi==null)qi=new JSONArray();if(ai==null)ai=new JSONArray();}catch(Exception ignored){}}
 void persist(){try{JSONObject d=new JSONObject().put("q",question).put("a",answer).put("qi",qi).put("ai",ai);prefs.edit().putString("draft:"+doc,d.toString()).apply();}catch(JSONException e){throw new IllegalStateException(e);}refresh();}
 void refresh(){if(summary!=null)summary.setText("문제 "+question.length()+"자 · 사진 "+qi.length()+"   /   정답 "+answer.length()+"자 · 사진 "+ai.length()+(busy?" · 사진 저장 중…":""));}
 View toolbar(){LinearLayout panel=a.col();panel.setPadding(0,a.dp(6),0,0);summary=a.text("",12,a.muted);panel.addView(summary);summary.setOnClickListener(v->edit());LinearLayout r=a.row();a.weighted(r,a.button("문제 붙여넣기",a.teal,()->paste(false)));a.weighted(r,a.button("정답 붙여넣기",0xFFAACFFF,()->paste(true)));a.weighted(r,a.button("✎ 편집·저장",0xFFF2CF80,this::edit));panel.addView(r);refresh();return panel;}
 void toast(String s){Toast.makeText(a,s,Toast.LENGTH_SHORT).show();}
 void paste(boolean target){ClipboardManager cm=a.getSystemService(ClipboardManager.class);ClipData clip=cm.getPrimaryClip();if(clip==null||clip.getItemCount()==0){toast("AI 셀렉트에서 복사한 뒤 눌러 주세요");return;}ClipData.Item item=clip.getItemAt(0);Uri uri=item.getUri();String mime=null;try{mime=uri==null?null:a.getContentResolver().getType(uri);}catch(SecurityException ignored){}if(uri!=null&&(clip.getDescription().hasMimeType("image/*")||(mime!=null&&mime.startsWith("image/")))){importImage(uri,target);return;}CharSequence t=item.getText();if(t==null||t.toString().trim().isEmpty()){toast("복사한 텍스트가 없습니다. 사진은 편집에서 첨부할 수 있습니다");return;}if(target)answer=append(answer,t.toString());else question=append(question,t.toString());persist();toast(target?"정답에 담았습니다":"문제에 담았습니다");}
 static String append(String old,String text){return old.isEmpty()?text:old+"\n"+text;}
 void pick(boolean target){pickerAnswer=target;prefs.edit().putLong("pickerDoc",doc).putBoolean("pickerAnswer",target).commit();if(editor!=null)editor.dismiss();a.startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("image/*").addCategory(Intent.CATEGORY_OPENABLE).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION),11);}
 void importImage(Uri uri,boolean target){if((target?ai:qi).length()>=6){toast("한 면에 사진은 6장까지 담을 수 있습니다");return;}if(busy){toast("사진을 저장하는 중입니다");return;}busy=true;refresh();a.render.execute(()->{File out=null,temp=null;try{File dir=new File(a.getFilesDir(),"clips");if(!dir.exists()&&!dir.mkdirs())throw new IOException("사진 폴더를 만들 수 없습니다");temp=new File(dir,UUID.randomUUID()+".part");try(InputStream in=a.getContentResolver().openInputStream(uri);OutputStream os=new FileOutputStream(temp)){if(in==null)throw new IOException("사진을 읽을 수 없습니다");byte[] b=new byte[65536];int n;long count=0;while((n=in.read(b))!=-1){count+=n;if(count>32L*1024*1024)throw new IOException("32MB 이하의 사진을 선택해 주세요");os.write(b,0,n);}}BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;BitmapFactory.decodeFile(temp.getPath(),options);if(options.outWidth<=0||options.outHeight<=0)throw new IOException("지원하지 않는 사진입니다");out=new File(dir,UUID.randomUUID()+".img");if(!temp.renameTo(out))throw new IOException("사진을 저장하지 못했습니다");final String path=out.getAbsolutePath();a.runOnUiThread(()->{busy=false;if(a.isDestroyed()){try{JSONObject latest=new JSONObject(prefs.getString("draft:"+doc,"{}"));JSONArray images=latest.optJSONArray(target?"ai":"qi");if(images==null)images=new JSONArray();images.put(path);latest.put(target?"ai":"qi",images);prefs.edit().putString("draft:"+doc,latest.toString()).commit();}catch(Exception ignored){}return;}if(target)ai.put(path);else qi.put(path);persist();toast(target?"정답 사진을 담았습니다":"문제 사진을 담았습니다");});}catch(Exception e){if(out!=null)out.delete();a.runOnUiThread(()->{busy=false;refresh();a.error(e);});}finally{if(temp!=null)temp.delete();}});}
 EditText field(String text,boolean target){EditText e=new EditText(a);e.setTextColor(a.fg);e.setHintTextColor(a.muted);e.setText(text);e.setMinLines(3);e.setGravity(Gravity.TOP);e.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int f){}public void onTextChanged(CharSequence s,int st,int before,int c){if(target)answer=s.toString();else question=s.toString();persist();}public void afterTextChanged(Editable s){}});return e;}
 void edit(){LinearLayout l=a.col();l.setPadding(a.dp(14),0,a.dp(14),0);l.addView(a.text("문제",15,a.teal));EditText q=field(question,false);l.addView(q);attachments(l,false);l.addView(a.button("＋ 문제 사진 첨부",a.teal,()->pick(false)));l.addView(a.button("선택한 문제 단어 가리기",a.teal,()->a.cloze(q)));l.addView(a.text("정답",15,0xFFAACFFF));EditText ans=field(answer,true);l.addView(ans);attachments(l,true);l.addView(a.button("＋ 정답 사진 첨부",0xFFAACFFF,()->pick(true)));l.addView(a.button("선택한 정답 단어 가리기",0xFFAACFFF,()->a.cloze(ans)));ScrollView s=new ScrollView(a);s.addView(l);AlertDialog dialog=new AlertDialog.Builder(a).setTitle("카드 작성").setView(s).setNegativeButton("문서로",null).setPositiveButton("카드 저장",null).create();editor=dialog;dialog.setOnShowListener(v->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(w->{if(busy){toast("사진 저장이 끝난 뒤 저장해 주세요");return;}if(question.trim().isEmpty()&&qi.length()==0){toast("문제를 담아 주세요");return;}if(answer.trim().isEmpty()&&ai.length()==0){toast("정답을 담아 주세요");return;}try{a.store.manual(doc,question,answer,qi.toString(),ai.toString());question="";answer="";qi=new JSONArray();ai=new JSONArray();persist();dialog.dismiss();toast("카드를 저장했습니다");}catch(Exception e){a.error(e);}}));dialog.show();}
 void attachments(LinearLayout parent,boolean target){JSONArray list=target?ai:qi;for(int i=0;i<list.length();i++){String path=list.optString(i);LinearLayout item=a.col();parent.addView(item);images(a,item,new JSONArray().put(path).toString());item.addView(a.button("사진 삭제",a.muted,()->{for(int n=0;n<list.length();n++)if(path.equals(list.optString(n))){list.remove(n);break;}persist();parent.removeView(item);}));}}
 static void images(MainActivity a,LinearLayout parent,String json){try{JSONArray paths=new JSONArray(json);for(int i=0;i<paths.length();i++){String path=paths.getString(i);ImageView view=new ImageView(a);view.setAdjustViewBounds(true);view.setScaleType(ImageView.ScaleType.FIT_CENTER);parent.addView(view,new LinearLayout.LayoutParams(-1,-2));final int token=a.generation;a.render.execute(()->{BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeFile(path,o);o.inSampleSize=1;o.inSampleSize=ImageLimits.sample(o.outWidth,o.outHeight);o.inJustDecodeBounds=false;Bitmap b=BitmapFactory.decodeFile(path,o);a.runOnUiThread(()->{if(b==null)return;if(token!=a.generation||a.isDestroyed()||!view.isAttachedToWindow()){b.recycle();return;}view.setImageBitmap(b);view.addOnAttachStateChangeListener(new View.OnAttachStateChangeListener(){public void onViewAttachedToWindow(View v){}public void onViewDetachedFromWindow(View v){view.setImageDrawable(null);b.recycle();}});});});}}catch(Exception e){parent.addView(a.text("사진을 열지 못했습니다",13,a.muted));}}
}
